#include <iostream>
#include <cmath>

int main() {
    int n = 0;
    if (!(std::cin >> n)) return 0;

    // 1. Prime check demonstration using do...while logic
    bool is_prime = true;
    if (n < 2) {
        is_prime = false;
    } else {
        int i = 2;
        do {
            if (i > n / 2) break;
            if (n % i == 0) {
                is_prime = false;
                break;
            }
            i++;
        } while (i <= n / 2);
    }
    std::cout << n << (is_prime ? " is prime\n" : " is composite\n");

    // 2. Loop with continue: print non-square numbers up to limit
    std::cout << "Non-squares up to " << n << ": ";
    for (int i = 1; i <= n; ++i) {
        int root = static_cast<int>(std::sqrt(i));
        if (root * root == i) {
            continue; // Skip perfect squares
        }
        std::cout << i << " ";
    }
    std::cout << "\n";

    return 0;
}

#include <iostream>

int main() {
    // 3D vector coordinates modeled as 1D arrays
    // Form 2: explicit size with full initialization
    double v1[3] = {1.0, 2.0, 3.0};

    // Form 3: deduced size from initializer list
    double v2[] = {4.0, 5.0, 6.0};

    // Dot product v1 . v2 using for loop
    double dot_product = 0.0;
    for (int i = 0; i < 3; ++i) {
        dot_product += v1[i] * v2[i];
    }

    // Form 2 with partial initialization: remaining elements become 0 in C++
    int arr[5] = {10, 20};

    std::cout << "Dot product: " << dot_product << "\n";
    std::cout << "Partial array: ";
    for (int i = 0; i < 5; ++i) {
        std::cout << arr[i] << " ";
    }
    std::cout << "\n";

    return 0;
}
